<script setup>
import {ref,onMounted,onUnmounted,onBeforeUnmount} from 'vue'
import {memberRpc} from './member-service.js'
import {SOFTWARE_HEADERS,SOFTWARE_FIELDS,kstInput,timestamp,numeric,remainingDays,softwareWorkbook} from './software-grid.js'
import {formatMemberDate} from './member-table.js'
const SHEET='https://docs.google.com/spreadsheets/d/1U4wzlb89jKt6sF8JU8Q0yE0d9xXcaGIMdYYXffA97fM/edit'
const rows=ref([]),conflicts=ref([]),sync=ref(null),message=ref(''),loading=ref(false),saving=ref(false),grid=ref(null);let timer,saveTimer,epoch=0,disposed=false
const meaningful=r=>SOFTWARE_FIELDS.some((k,c)=>![6,9].includes(c)&&r[k]!==''&&r[k]!==null&&r[k]!==undefined&&r[k]!==0)
const blank=()=>({_key:crypto.randomUUID(),_edit:0,_dirty:false,issued_at:null,work_name:'',target:'',software_name:'',admin_id:'',expires_at:null,quantity:0,unit_price:0,memo:''})
const sorted=list=>list.sort((a,b)=>(b.issued_at?Date.parse(b.issued_at):-Infinity)-(a.issued_at?Date.parse(a.issued_at):-Infinity)||String(a.id||a._key).localeCompare(String(b.id||b._key)))
async function load(force=false){if(saving.value||(!force&&(rows.value.some(r=>r._dirty)||grid.value?.contains(document.activeElement))))return;const id=++epoch;loading.value=true;try{const data=await memberRpc('software_list');if(disposed||id!==epoch)return;rows.value=sorted(data.rows.map(r=>({...r,_key:r.id,_edit:0,_dirty:false})));conflicts.value=data.conflicts;sync.value=data.sync;message.value='';if(!rows.value.length)rows.value.push(blank())}catch(e){if(id===epoch&&!disposed)message.value=e.message}finally{if(id===epoch&&!disposed)loading.value=false}}
function change(r,c,value){try{const key=SOFTWARE_FIELDS[c];r[key]=c===0||c===5?timestamp(value):c===7||c===8?numeric(value):String(value);r._dirty=true;++r._edit;clearTimeout(saveTimer);saveTimer=setTimeout(save,600)}catch(e){message.value=e.message}}
async function save(){if(saving.value)return false;const pending=rows.value.filter(r=>r._dirty&&meaningful(r));if(!pending.length)return true;saving.value=true;const generations=pending.map(r=>r._edit);try{const result=await memberRpc('software_save',{p_rows:pending.map(r=>Object.fromEntries(['id','version',...SOFTWARE_FIELDS.filter((_,i)=>![6,9].includes(i))].map(k=>[k,r[k]])))});if(disposed)return false;result.forEach((saved,i)=>{const local=pending[i];if(local._edit===generations[i])Object.assign(local,saved,{_dirty:false});else Object.assign(local,{id:saved.id,version:saved.version});local._key=saved.id});message.value='저장했습니다. Google 스프레드시트는 다음 자동 동기화에서 반영됩니다.';if(rows.value.some(r=>r._dirty&&meaningful(r)))saveTimer=setTimeout(save,600);return true}catch(e){message.value=e.message+' 입력한 내용은 화면에 보존되어 있습니다.';return false}finally{if(!disposed)saving.value=false}}
async function refresh(){if(rows.value.some(r=>r._dirty)&&!confirm('저장되지 않은 편집을 취소하고 최신 데이터를 불러오시겠습니까?'))return;await load(true)}
function add(){rows.value.push(blank())}
async function leaveGrid(e){if(grid.value?.contains(e.relatedTarget))return;await save();if(!disposed&&!saving.value)rows.value=sorted(rows.value.slice())}
function moveCell(e,r,c){if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)||((e.key==='ArrowLeft'||e.key==='ArrowRight')&&typeof e.target.selectionStart==='number'&&e.target.selectionStart!==0&&e.target.selectionStart!==e.target.value?.length))return;const dr=e.key==='ArrowDown'?1:e.key==='ArrowUp'?-1:0,dc=e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0;let next=c+dc;while(dc&&[6,9].includes(next))next+=dc;const target=grid.value?.querySelector('[data-row="'+(r+dr)+'"][data-col="'+next+'"]');if(target){e.preventDefault();target.focus()}}
function paste(e,start,c){const text=e.clipboardData?.getData('text/plain');if(!text||!/[\t\n]/.test(text))return;e.preventDefault();const matrix=text.replace(/\r/g,'').replace(/\n$/,'').split('\n').map(x=>x.split('\t'));if(matrix.length>500){message.value='한 번에 500행 이하로 붙여넣어 주세요.';return}matrix.forEach((line,i)=>{if(!rows.value[start+i])rows.value.push(blank());line.forEach((v,j)=>{const col=c+j;if(col<11&&![6,9].includes(col))change(rows.value[start+i],col,v)})})}
async function excel(){if(!await save())return;const data=softwareWorkbook(sorted(rows.value.filter(meaningful).slice()));const url=URL.createObjectURL(new Blob([data],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));const a=document.createElement('a');a.href=url;a.download='피엠오피스_소프트웨어발급현황_'+kstInput(new Date().toISOString()).slice(0,10)+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function resolve(c,choice){const row=rows.value.find(r=>r.id===c.record_id);if(!row||!confirm(choice==='sheet'?'시트 수정값을 적용하시겠습니까?':'웹의 현재 값을 유지하시겠습니까?'))return;try{await memberRpc('software_resolve',{p_conflict:c.id,p_choice:choice,p_version:row.version});await load(true)}catch(e){message.value=e.message}}
async function sheet(){if(await save()){window.open(SHEET,'_blank','noopener');message.value='저장된 자료는 다음 자동 동기화에서 Google 스프레드시트에 반영됩니다.'}}
onMounted(()=>{load();timer=setInterval(()=>load(),10000)})
onBeforeUnmount(()=>{clearTimeout(saveTimer);if(!saving.value&&rows.value.some(r=>r._dirty&&meaningful(r)))save()})
onUnmounted(()=>{disposed=true;++epoch;clearInterval(timer);clearTimeout(saveTimer)})
</script>
<template><main class="member-page software-admin"><h1>소프트웨어 발급 현황</h1><p>셀을 바로 편집하고 Tab·방향키로 이동하거나 스프레드시트의 여러 셀을 붙여넣을 수 있습니다. 날짜는 한국시간(KST)이며 최근 발급일 순으로 표시합니다.</p><div class="software-actions"><button @click="add" :disabled="saving">행 추가</button><button @click="save" :disabled="saving">{{saving?'저장 중…':'변경 저장'}}</button><button @click="refresh" :disabled="saving||loading">새로고침·발급일 정렬</button><details><summary>내보내기</summary><button @click="excel">엑셀(.xlsx)로 내보내기</button><button @click="sheet">Google 스프레드시트로 내보내기</button></details></div><p role="status" aria-live="polite">{{loading?'불러오는 중…':message}}</p><p class="software-sync">양방향 자동 동기화: {{sync?.last_sync_at?formatMemberDate(sync.last_sync_at)+' KST':'연결 확인 중'}}<span v-if="sync?.last_error"> · {{sync.last_error}}</span></p><div ref="grid" class="software-grid" @focusout="leaveGrid" tabindex="0" role="region" aria-label="소프트웨어 발급 편집 표"><table><thead><tr><th>#</th><th v-for="(h,c) in SOFTWARE_HEADERS" :key="h">{{h}}<small v-if="[6,9].includes(c)">자동 계산</small></th></tr></thead><tbody><tr v-for="(r,i) in rows" :key="r._key" :class="{'software-conflict':r.conflict}"><th>{{i+1}}<span v-if="r._dirty" aria-label="미저장"> *</span></th><td v-for="(key,c) in SOFTWARE_FIELDS" :key="key"><output v-if="c===6">{{remainingDays(r.expires_at)}}</output><output v-else-if="c===9">{{new Intl.NumberFormat('ko-KR',{maximumFractionDigits:2}).format((Number(r.quantity)||0)*(Number(r.unit_price)||0))}}</output><input v-else :aria-label="(i+1)+'행 '+SOFTWARE_HEADERS[c]" :data-row="i" :data-col="c" :type="c===0||c===5?'datetime-local':c===7||c===8?'number':'text'" :step="c===7?'0.001':c===8?'0.01':undefined" :min="c===7||c===8?0:undefined" :value="c===0||c===5?kstInput(r[key]):r[key]" :maxlength="c===10?5000:1000" @change="change(r,c,$event.target.value)" @keydown="moveCell($event,i,c)" @paste="paste($event,i,c)"></td></tr></tbody></table></div><section v-if="conflicts.length" class="software-conflicts"><h2>동시 수정 확인</h2><article v-for="c in conflicts" :key="c.id"><p>{{rows.find(r=>r.id===c.record_id)?.software_name}} · 웹과 시트에서 동시에 수정했습니다.</p><p>시트 수정값: {{c.incoming.work_name}} / {{c.incoming.software_name}} / 수량 {{c.incoming.quantity}} / 단가 {{c.incoming.unit_price}} / 메모 {{c.incoming.memo}}</p><button @click="resolve(c,'web')">웹 값 유지</button><button @click="resolve(c,'sheet')">시트 값 적용</button></article></section></main></template>
<style scoped>.software-admin p{line-height:1.75;margin:14px 0}.software-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:22px 0}.software-actions button,.software-conflicts button{padding:10px 14px;border:1px solid #aec2d9;border-radius:6px;background:#edf3fa;font-weight:650}.software-actions details{position:relative}.software-actions summary{padding:10px 14px;border:1px solid #aec2d9;border-radius:6px;cursor:pointer;font-weight:650}.software-actions details[open]{background:white;z-index:5}.software-actions details button{display:block;white-space:nowrap;margin-top:7px}.software-sync{font-size:13px;color:#536c84}.software-grid{overflow:auto;border:1px solid #c7d6e6;max-height:70vh;max-width:100%}.software-grid table{border-collapse:separate;border-spacing:0;min-width:1950px;width:100%;font-size:13px}.software-grid th,.software-grid td{border-right:1px solid #dce5ee;border-bottom:1px solid #dce5ee;text-align:left;vertical-align:middle}.software-grid thead th{position:sticky;top:0;z-index:2;background:#eaf2fc;padding:13px 10px;font-weight:700}.software-grid thead small{display:block;font-size:10px;font-weight:400}.software-grid tbody th{padding:10px;background:#f4f7fb;min-width:45px}.software-grid input{border:0;border-radius:0;background:transparent;padding:11px 9px;min-width:140px;width:100%;color:#17334f}.software-grid input[type=datetime-local]{min-width:210px}.software-grid td:nth-child(3) input,.software-grid td:last-child input{min-width:240px}.software-grid output{display:block;min-width:115px;padding:11px 9px;background:#f4f7fa;text-align:right}.software-grid input:focus{outline:2px solid #2362c3;outline-offset:-2px;background:#f8fbff}.software-conflict td{background:#fff4dc}.software-conflicts article{padding:18px;border:1px solid #e3bd77;margin:16px 0;overflow-wrap:anywhere}.software-conflicts button{margin:8px 10px 0 0}.software-conflicts h2{font-size:22px;font-weight:700;margin:24px 0}</style>
